    // ══════════════════════════════════════════════════════════════════
    // HTTP 客户端
    // ══════════════════════════════════════════════════════════════════
    async function fetchClaudeStatus() {
      const response = await fetch(STATUS_ROUTE, { credentials: "same-origin" });
